                Set-Content -LiteralPath $agentsMd -Value $newContent -Encoding UTF8 -NoNewline
                Write-Ok "Bloque SERENA removido de AGENTS.md"
            } else { Write-Ok "Sin bloque SERENA en AGENTS.md" }
        }
